export const FRONTEND_STYLE_PATH: string = "/assets/style.css"
export const FRONTEND_STYLE: string = ":root{color:#242722;font-synthesis:none;text-rendering:optimizelegibility;background:#f4f1e8;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,Segoe UI,sans-serif}*{box-sizing:border-box}body{min-width:320px;min-height:100vh;margin:0}button,input{font:inherit}button{cursor:pointer}.page-shell{background:radial-gradient(circle at 12% 10%,#e3643a24,#0000 31rem),linear-gradient(120deg,#0000 0 49.8%,#2427220f 50%,#0000 50.2%);min-height:100vh;padding:clamp(24px,8vw,96px) 20px}.todo-card{background:#fffdf7f0;border:1px solid #242722;border-radius:2px;width:min(720px,100%);margin:0 auto;box-shadow:14px 14px #d6cfbd}.masthead,.todo-form,.list-heading,.empty-state,.error,footer{padding-left:clamp(24px,6vw,56px);padding-right:clamp(24px,6vw,56px)}.masthead{border-bottom:1px solid #242722;padding-top:48px;padding-bottom:34px}.eyebrow{color:#d74f27;letter-spacing:.14em;text-transform:uppercase;margin:0 0 12px;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.74rem;font-weight:700}h1,h2,p{margin-top:0}h1{letter-spacing:-.055em;max-width:560px;margin-bottom:10px;font-family:Georgia,Times New Roman,serif;font-size:clamp(2.55rem,9vw,5rem);font-weight:400;line-height:.9}.lede{color:#66685f;max-width:480px;margin-bottom:0;line-height:1.6}.todo-form{border-bottom:1px solid #242722;padding-top:30px;padding-bottom:30px}.todo-form label{letter-spacing:.08em;text-transform:uppercase;margin-bottom:8px;font-size:.78rem;font-weight:700;display:block}.input-row{grid-template-columns:1fr auto;display:grid}.input-row input{background:#fffdf7;border:1px solid #242722;border-right:0;border-radius:0;outline:0;min-width:0;padding:14px 16px}.input-row input:focus{box-shadow:inset 0 0 0 2px #d74f27}.input-row button{color:#fffdf7;background:#242722;border:1px solid #242722;border-radius:0;min-width:96px;padding:0 18px;font-weight:700}.input-row button:disabled{cursor:not-allowed;opacity:.45}.list-heading{justify-content:space-between;align-items:baseline;padding-top:26px;padding-bottom:16px;display:flex}.list-heading h2{margin-bottom:0;font-family:Georgia,Times New Roman,serif;font-size:1.65rem;font-weight:400}.list-heading span,footer{color:#77786f;text-transform:uppercase;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.72rem}.todo-list{border-top:1px solid #d7d1c2;margin:0;padding:0;list-style:none}.todo-row{border-bottom:1px solid #d7d1c2;grid-template-columns:auto 1fr auto;align-items:center;gap:16px;min-height:66px;padding:12px clamp(24px,6vw,56px);display:grid}.todo-check{color:#fffdf7;background:0 0;border:1px solid #242722;border-radius:50%;place-items:center;width:24px;height:24px;padding:0;display:grid}.is-complete .todo-check{background:#d74f27;border-color:#d74f27}.todo-title{line-height:1.4}.is-complete .todo-title{color:#8c8b82;text-decoration:line-through}.todo-delete{color:#8b3f2b;text-transform:uppercase;background:0 0;border:0;padding:4px 0;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.7rem}.empty-state{color:#77786f;border-top:1px solid #d7d1c2;margin-bottom:0;padding-top:26px;padding-bottom:48px}.error{color:#7c2d18;background:#f9e5dc;border-left:3px solid #d74f27;margin:18px clamp(24px,6vw,56px) 0;padding:12px 14px}footer{flex-wrap:wrap;gap:12px;padding-top:20px;padding-bottom:22px;display:flex}@media (width<=520px){.page-shell{padding:0}.todo-card{min-height:100vh;box-shadow:none;border-width:0}.input-row{grid-template-columns:1fr;gap:8px}.input-row input{border-right:1px solid #242722}.input-row button{min-height:48px}}\n/*$vite$:1*/"
